import React, { Component } from 'react';
import { CButton, CCard, CCardBody, CCol, CContainer, CInput, CRow } from '@coreui/react';
import { requestHeaderPOSTWithAuth, requestHeaderGETWithAuth } from 'src/Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { Logger, reloadPage } from '../../Utils/Utils';
import { BACKEND_NEXUS_APP_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';

const FILE_NAME = "LinkGulper.js";

const POLL_INTERVAL_MS = 200;

class LinkGulper extends Component {

    constructor(props) {
        super(props);
        this.state = {
            gulping: true,
            currentLink: '',
            lastSavedLink: '',
            savedCount: 0,
            status: 'Idle',
            savedLinks: [], // most-recent first
            assigning: false,
            assignResult: null, // last assign-tenants outcome (string) or null
        };
        this._timer = null;
        this._inFlight = false;
    }

    componentDidMount() {
        document.title = "Link Gulper";
        this.startGulping();
    }

    componentWillUnmount() {
        this.stopGulping();
    }

    startGulping = () => {
        this.setState({ gulping: true, status: 'Gulping…' });
        this.scheduleNextPoll();
    }

    stopGulping = () => {
        if (this._timer) {
            clearTimeout(this._timer);
            this._timer = null;
        }
        this.setState({ gulping: false, status: 'Stopped' });
    }

    toggleGulping = () => {
        if (this.state.gulping) {
            this.stopGulping();
        } else {
            this.startGulping();
        }
    }

    scheduleNextPoll = () => {
        this._timer = setTimeout(() => {
            this.readFromClipboard();
            if (this.state.gulping) {
                this.scheduleNextPoll();
            }
        }, POLL_INTERVAL_MS);
    }

    readFromClipboard = () => {
        if (!navigator.clipboard || !navigator.clipboard.readText) {
            this.setState({ status: 'Clipboard API not available' });
            return;
        }

        navigator.clipboard.readText()
            .then((clipText) => {
                const link = (clipText || '').trim();
                if (link.length === 0) return;

                this.setState({ currentLink: link });

                // Only save when it changes from the last saved link (avoids hammering the API).
                if (link !== this.state.lastSavedLink) {
                    this.saveLink(link);
                }
            })
            .catch((error) => {
                // Reading the clipboard can fail if the document is not focused; keep gulping quietly.
                Logger(FILE_NAME, "readFromClipboard", "ERROR", "error", error);
            });
    }

    // Extract a human-readable status string from a successful (HTTP 200) response body.
    // The backend returns GeneralResponse with the outcome in `data` (SaveLinkResult
    // {link, inserted, message}); prefer data.message, then the top-level message, then a
    // stringified fallback so the status always reflects what the API actually said.
    statusFromBody = (body) => {
        if (body == null) return 'Saved';
        const data = body.data;
        if (data != null) {
            if (typeof data === 'object') {
                if (data.message) return String(data.message);
                return JSON.stringify(data);
            }
            return String(data);
        }
        if (body.message) return String(body.message);
        return 'Saved';
    }

    saveLink = (link) => {
        if (this._inFlight) return;
        this._inFlight = true;

        const userData = getUserDataFromLocalStorage();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/link-depot';
        const payload = JSON.stringify({ link });
        const startedAt = (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();

        this.setState({ status: 'Saving: ' + link });

        // Resolve status + body together (don't throw on non-200) so the status line can be
        // driven directly by what the backend returned.
        fetch(API_URL, requestHeaderPOSTWithAuth(payload, userData.authToken))
        .then(response => {
            if (response.status === 401) { logoutProcedureForLocalStorage(); reloadPage(); }
            return response.json()
                .then(body => ({ status: response.status, body }))
                .catch(() => ({ status: response.status, body: null }));
        })
        .then(({ status, body }) => {
            const nowMs = (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
            const timeTakenMs = Math.round(nowMs - startedAt);
            Logger(FILE_NAME, "saveLink", "RESULT", "result", { status, body, timeTakenMs });

            if (status === 200) {
                const statusText = this.statusFromBody(body);
                // Server-side processing time, reported by the backend on GeneralResponse.
                const serverTimeMs = (body != null && body.timeTakenInMs != null) ? body.timeTakenInMs : null;
                const timingText = serverTimeMs != null
                    ? ' (' + timeTakenMs + ' ms round-trip, ' + serverTimeMs + ' ms server)'
                    : ' (' + timeTakenMs + ' ms)';
                this.setState(prev => ({
                    lastSavedLink: link,
                    savedCount: prev.savedCount + 1,
                    status: statusText + timingText,
                    savedLinks: [{ link, at: new Date().toLocaleTimeString(), status: statusText, timeTakenMs, serverTimeMs }, ...prev.savedLinks].slice(0, 50),
                }));
            } else {
                const failText = 'API failed ❌ - ' + status;
                this.setState(prev => ({
                    status: failText + ' (' + timeTakenMs + ' ms)',
                    savedLinks: [{ link, at: new Date().toLocaleTimeString(), status: failText, timeTakenMs }, ...prev.savedLinks].slice(0, 50),
                }));
            }
        })
        .catch(error => {
            const nowMs = (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
            const timeTakenMs = Math.round(nowMs - startedAt);
            Logger(FILE_NAME, "saveLink", "ERROR", "error", error);
            this.setState(prev => ({
                status: 'API failed ❌ - network/error (' + timeTakenMs + ' ms)',
                savedLinks: [{ link, at: new Date().toLocaleTimeString(), status: 'API failed ❌ - network/error', timeTakenMs }, ...prev.savedLinks].slice(0, 50),
            }));
        })
        .finally(() => {
            this._inFlight = false;
        });
    }

    manualSave = (e) => {
        e.preventDefault();
        const link = (this.state.currentLink || '').trim();
        if (link.length === 0) return;
        this.saveLink(link);
    }

    saveClipboardNow = () => {
        if (!navigator.clipboard || !navigator.clipboard.readText) {
            this.setState({ status: 'Clipboard API not available' });
            return;
        }

        navigator.clipboard.readText()
            .then((clipText) => {
                const link = (clipText || '').trim();
                if (link.length === 0) {
                    this.setState({ status: 'Clipboard is empty' });
                    return;
                }
                this.setState({ currentLink: link });
                this.saveLink(link);
            })
            .catch((error) => {
                Logger(FILE_NAME, "saveClipboardNow", "ERROR", "error", error);
                this.setState({ status: 'Could not read clipboard (focus the tab and allow access)' });
            });
    }

    // Trigger the backend job that matches depot links to tenants by base domain.
    // GET /v1/link-depot/assign-tenants -> 200 with the outcome in `data`.
    assignTenants = () => {
        if (this.state.assigning) return;

        const userData = getUserDataFromLocalStorage();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/link-depot/assign-tenants';

        this.setState({ assigning: true, assignResult: null, status: 'Assigning tenants…' });

        fetch(API_URL, requestHeaderGETWithAuth(userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) { logoutProcedureForLocalStorage(); reloadPage(); }
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "assignTenants", "SUCCESS", "result", result);
            if (!result) return;
            const data = result.data;
            const summary = (data == null)
                ? 'Done'
                : (typeof data === 'object' ? JSON.stringify(data) : String(data));
            this.setState({ assignResult: summary, status: 'Tenants assigned ✔' });
        })
        .catch(error => {
            Logger(FILE_NAME, "assignTenants", "ERROR", "error", error);
            this.setState({ assignResult: null, status: 'Error assigning tenants' });
        })
        .finally(() => {
            this.setState({ assigning: false });
        });
    }

    render() {
        const { gulping, currentLink, lastSavedLink, savedCount, status, savedLinks, assigning, assignResult } = this.state;

        return (
            <div>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>
                    <h2>🫗 Link Gulper</h2>
                    <div style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
                        <span style={{
                            padding: '4px 12px',
                            borderRadius: '12px',
                            fontWeight: 'bold',
                            backgroundColor: gulping ? '#e8f5e9' : '#ffebee',
                            color: gulping ? '#2e7d32' : '#c62828',
                        }}>
                            {gulping ? '● Gulping' : '○ Stopped'}
                        </span>
                        <CButton color={gulping ? 'danger' : 'success'} onClick={this.toggleGulping}>
                            {gulping ? 'Stop' : 'Start'}
                        </CButton>
                        <CButton color="info" onClick={this.assignTenants} disabled={assigning} title="Match depot links to tenants by base domain">
                            {assigning ? 'Assigning…' : '🏷️ Assign Tenants'}
                        </CButton>
                    </div>
                </div>

                <CContainer>
                    <CRow className="justify-content-center">
                        <CCol md="8">
                            <CCard className="p-4">
                                <CCardBody>
                                    <p style={{ color: '#6c757d' }}>
                                        Aggressively reads your clipboard every {POLL_INTERVAL_MS}ms and saves any new link to the depot.
                                        Keep this tab focused so the browser allows clipboard access.
                                    </p>

                                    <CButton
                                        color="success"
                                        onClick={this.saveClipboardNow}
                                        style={{
                                            width: '100%',
                                            padding: '24px',
                                            fontSize: '1.6rem',
                                            fontWeight: 700,
                                            marginBottom: '20px',
                                        }}
                                    >
                                        🫗 Save Clipboard Now
                                    </CButton>

                                    <form onSubmit={this.manualSave}>
                                        <label><strong>Current clipboard link</strong></label>
                                        <div style={{ display: 'flex', gap: '8px', marginBottom: '12px' }}>
                                            <CInput
                                                type="text"
                                                value={currentLink}
                                                placeholder="Copy a link to auto-save…"
                                                onChange={(e) => this.setState({ currentLink: e.target.value })}
                                            />
                                            <CButton color="primary" type="submit">Save</CButton>
                                        </div>
                                    </form>

                                    <div style={{ display: 'flex', gap: '24px', marginBottom: '8px' }}>
                                        <div><strong>Saved:</strong> {savedCount}</div>
                                        <div><strong>Status:</strong> {status}</div>
                                    </div>
                                    <div style={{ marginBottom: '4px' }}>
                                        <strong>Last saved:</strong> <span style={{ wordBreak: 'break-all' }}>{lastSavedLink || '—'}</span>
                                    </div>
                                    {assignResult != null && (
                                        <div style={{ marginBottom: '4px' }}>
                                            <strong>Assign tenants result:</strong> <span style={{ wordBreak: 'break-all' }}>{assignResult}</span>
                                        </div>
                                    )}

                                    <hr />
                                    <h5>Recently saved</h5>
                                    {savedLinks.length === 0 ? (
                                        <p style={{ color: '#6c757d', fontStyle: 'italic' }}>Nothing saved yet.</p>
                                    ) : (
                                        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                                            <thead>
                                                <tr style={{ borderBottom: '2px solid #dee2e6', textAlign: 'left' }}>
                                                    <th style={{ padding: '6px' }}>#</th>
                                                    <th style={{ padding: '6px' }}>Time</th>
                                                    <th style={{ padding: '6px' }}>Link</th>
                                                    <th style={{ padding: '6px' }}>Status</th>
                                                    <th style={{ padding: '6px', whiteSpace: 'nowrap' }}>Took (ms)</th>
                                                    <th style={{ padding: '6px', whiteSpace: 'nowrap' }}>Server (ms)</th>
                                                </tr>
                                            </thead>
                                            <tbody>
                                                {savedLinks.map((entry, index) => (
                                                    <tr key={index} style={{ borderBottom: '1px solid #dee2e6' }}>
                                                        <td style={{ padding: '6px' }}>{savedLinks.length - index}</td>
                                                        <td style={{ padding: '6px', whiteSpace: 'nowrap' }}>{entry.at}</td>
                                                        <td style={{ padding: '6px', wordBreak: 'break-all' }}>{entry.link}</td>
                                                        <td style={{ padding: '6px', wordBreak: 'break-word' }}>{entry.status != null ? entry.status : '—'}</td>
                                                        <td style={{ padding: '6px', whiteSpace: 'nowrap', textAlign: 'right' }}>{entry.timeTakenMs != null ? entry.timeTakenMs : '—'}</td>
                                                        <td style={{ padding: '6px', whiteSpace: 'nowrap', textAlign: 'right' }}>{entry.serverTimeMs != null ? entry.serverTimeMs : '—'}</td>
                                                    </tr>
                                                ))}
                                            </tbody>
                                        </table>
                                    )}
                                </CCardBody>
                            </CCard>
                        </CCol>
                    </CRow>
                </CContainer>
            </div>
        );
    }
}

export default LinkGulper;
